function auditR44NativeStopLogs(result,pages){
 const lines=[...pages].reverse().flatMap(p=>p.items),parse=kind=>lines.filter(l=>l.includes("Order "+kind+" |")&&l.includes(" STOP |")).map(l=>{
  const m=l.match(/\[INFO \| ([^\]]+)\].*\| (BUY|SELL) STOP \| Qty: ([0-9.eE+-]+) \| Price: ([0-9.eE+-]+)/);if(!m)throw Error("stop log format");
  return {time:Date.parse(m[1]+"Z"),side:m[2],qty:Number(m[3]),price:Number(m[4])};
 });
 const submitted=parse("submitted"),canceled=parse("canceled");
 if(submitted.length!==result.N)throw Error("stop submission count");
 let cancellationCount=0,maxDisplayPriceError=0;const used=new Set;
 for(const t of result.records){const o=t.opening_log,side=t.side==="long"?"SELL":"BUY",s=submitted.filter(z=>z.time===t.opened_at);if(s.length!==1||s[0].side!==side||Math.abs(s[0].qty-t.qty)>1e-8)throw Error("initial stop native log");const err=Math.abs(s[0].price-o.stop);maxDisplayPriceError=Math.max(maxDisplayPriceError,err);
  // The native prose logger renders prices at 2 decimals; exact executed order
  // prices and planned structural levels are reconciled separately.
  if(err>.01000001)throw Error("displayed stop price");
  const exit=t.orders.find(z=>z.reduce_only&&z.status==="EXECUTED");if(exit.type==="MARKET"){
   const cs=canceled.map((x,i)=>({x,i})).filter(({x})=>x.time===t.closed_at&&x.side===side&&Math.abs(x.qty-t.qty)<1e-8&&Math.abs(x.price-o.stop)<=.01000001);
   if(cs.length!==1||used.has(cs[0].i))throw Error("native stop cancellation at market close");used.add(cs[0].i);cancellationCount++;
  }
 }
 if(used.size!==canceled.length)throw Error("extra native stop cancellation");
 return {status:"PASS_NATIVE_STOP_SUBMISSION_AND_CANCELLATION_LOGS",submitted:submitted.length,canceled:cancellationCount,maxDisplayPriceError,limit:"Canceled protective orders omitted from per-trade snapshot; prose logs provide submission/cancellation timestamps and rounded prices, not an exchange order ledger."};
}
